import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import stat
import subprocess
import time

pipeline = 'find . -type f -print0 | sort -z | xargs -0 sha256sum | sha256sum'
inner_pipeline = 'find . -type f -print0 | sort -z | xargs -0 sha256sum'
forced_environment = dict(os.environ, LC_ALL='C')

def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()

def process(pid):
    path = Path('/proc') / str(pid)
    try:
        fields = (path / 'stat').read_text().rsplit(')', 1)[1].split()
        return {'pid': pid, 'present': True, 'state': fields[0], 'start_ticks': int(fields[19])}
    except FileNotFoundError:
        return {'pid': pid, 'present': False}

def inventory(root):
    records = []
    file_count = 0
    byte_count = 0
    unsupported = []
    unsafe = []
    def fail(error):
        raise error
    for base, directories, files in os.walk(root, topdown=True, followlinks=False, onerror=fail):
        for name in directories + files:
            path = Path(base) / name
            relative = str(path.relative_to(root))
            details = path.lstat()
            records.append([relative, details.st_dev, details.st_ino, details.st_mode, details.st_size, details.st_mtime_ns, details.st_ctime_ns])
            if not all(32 <= ord(character) <= 126 for character in relative) or '\\' in relative:
                unsafe.append(relative)
            if stat.S_ISREG(details.st_mode):
                file_count += 1
                byte_count += details.st_size
            elif not stat.S_ISDIR(details.st_mode):
                unsupported.append(relative)
    records.sort(key=lambda value: value[0].encode('utf-8'))
    digest = hashlib.sha256(json.dumps(records, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode()).hexdigest()
    return {'stat_inventory_sha256': digest, 'entries_including_directories': len(records), 'regular_files': file_count, 'regular_bytes': byte_count, 'nonregular_nondirectory_paths': unsupported, 'unsafe_checksum_pathnames': unsafe}

def markers(root):
    result = {}
    for name in ('FAILED.json', 'SEAL.json', 'FINALIZED.json', 'RESOURCE.json', 'FINALIZATION_ABORT.json', 'PUBLICATION_ABORT.json'):
        path = root / name
        try:
            details = path.lstat()
            entry = {'present': True, 'regular': stat.S_ISREG(details.st_mode), 'bytes': details.st_size}
            if entry['regular']:
                checksum = hashlib.sha256()
                with path.open('rb') as stream:
                    for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                        checksum.update(chunk)
                entry['sha256'] = checksum.hexdigest()
            result[name] = entry
        except FileNotFoundError:
            result[name] = {'present': False}
    return result

