        result['hash_started_utc'] = now()
        timer = time.perf_counter()
        outer = subprocess.run(['bash', '-o', 'pipefail', '-c', pipeline], cwd=root, env=forced_environment, capture_output=True, check=False, timeout=60)
        result['full_pipeline_duration_seconds'] = round(time.perf_counter() - timer, 6)
        result['full_pipeline_exit_code'] = outer.returncode
        result['full_pipeline_stdout'] = outer.stdout.decode('ascii')
        result['full_pipeline_stderr'] = outer.stderr.decode('utf-8', 'replace')
        match = re.fullmatch(rb'([0-9a-f]{64})  -\n', outer.stdout)
        if outer.returncode != 0 or outer.stderr or match is None:
            raise ValueError('Explicit-C full pipeline failed')
        result['complete_root_stream_sha256_C'] = match.group(1).decode('ascii')
        result['inventory_between_passes'] = inventory(root)
