            files[name] = parsed.group(1).decode('ascii')
            ordered_paths.append(name)
        if ordered_paths != sorted(ordered_paths, key=lambda value: value.encode('ascii')):
            raise ValueError('Explicit-C stream is not byte sorted')
        result['regular_files'] = len(files)
        result['checksum_stream_bytes'] = len(inner.stdout)
